import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.CWgsre3x.js";const _=JSON.parse('{"title":"Πρόσβαση, δικαιώματα και σφάλματα συνεδρίας","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/access-and-session.md","filePath":"el/help/access-and-session.md"}'),o={name:"el/help/access-and-session.md"};function d(l,t,i,n,c,h){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="προσβαση-δικαιωματα-και-σφαλματα-συνεδριας" tabindex="-1">Πρόσβαση, δικαιώματα και σφάλματα συνεδρίας <a class="header-anchor" href="#προσβαση-δικαιωματα-και-σφαλματα-συνεδριας" aria-label="Permalink to &quot;Πρόσβαση, δικαιώματα και σφάλματα συνεδρίας&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="δεν-μπορω-να-συνδεθω-η-να-ανοιξω-ενοτητα" tabindex="-1">Δεν μπορώ να συνδεθώ ή να ανοίξω ενότητα <a class="header-anchor" href="#δεν-μπορω-να-συνδεθω-η-να-ανοιξω-ενοτητα" aria-label="Permalink to &quot;Δεν μπορώ να συνδεθώ ή να ανοίξω ενότητα&quot;">​</a></h2><p>Επιβεβαιώστε το σωστό εξουσιοδοτημένο περιβάλλον, εταιρεία και λογαριασμό. Αν έληξε η συνεδρία, χρησιμοποιήστε την κανονική σύνδεση. Η επιλογή ρόλου επίδειξης δεν παρέχει πραγματικά δικαιώματα.</p><h2 id="τι-σημαινουν-τα-σφαλματα-api" tabindex="-1">Τι σημαίνουν τα σφάλματα API; <a class="header-anchor" href="#τι-σημαινουν-τα-σφαλματα-api" aria-label="Permalink to &quot;Τι σημαίνουν τα σφάλματα API;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Κωδικός</th><th>Τι να ελέγξετε</th></tr></thead><tbody><tr><td>401</td><td>Απουσία ή μη έγκυρη πιστοποίηση. Επαναφέρετε την εγκεκριμένη συνεδρία.</td></tr><tr><td>400</td><td>Απαιτείται επιλογή εταιρείας ή διόρθωση στοιχείων αιτήματος.</td></tr><tr><td>403</td><td>Απαγόρευση εταιρικής πρόσβασης ή δικαιώματος. Επικοινωνήστε με διαχειριστή.</td></tr><tr><td>503</td><td>Μη διαθέσιμη απαιτούμενη υπηρεσία ή εξουσιοδότηση. Μην παρακάμπτετε τον έλεγχο.</td></tr></tbody></table><p>Πρόκειται για συνήθεις κατηγορίες και όχι πλήρη κατάλογο. Ελέγξτε τον πραγματικό κωδικό σφάλματος. Αποφύγετε επαναλαμβανόμενες εγγραφές όταν το αποτέλεσμα είναι αβέβαιο.</p><h2 id="στοιχεια-υποστηριξης" tabindex="-1">Στοιχεία υποστήριξης <a class="header-anchor" href="#στοιχεια-υποστηριξης" aria-label="Permalink to &quot;Στοιχεία υποστήριξης&quot;">​</a></h2><p>Δώστε έκδοση, ενότητα, ώρα, επιτρεπόμενο εταιρικό πλαίσιο και σφάλμα χωρίς ευαίσθητα στοιχεία. Μην κοινοποιείτε κωδικούς, tokens, cookies ή διαπιστευτήρια.</p><p>Δείτε <a href="/el/developers/authentication.html">Πιστοποίηση</a> και <a href="/el/developers/permissions.html">Δικαιώματα</a>.</p>',10)])])}const m=e(o,[["render",d]]);export{_ as __pageData,m as default};
